const systemPrefixFields=[['jobs','jobPrefix','Job Card Prefix'],['customers','customerPrefix','Customer Prefix'],['bikes','vehiclePrefix','Vehicle Prefix'],['staff','mechanicPrefix','Mechanic Prefix'],['parts','partPrefix','Spare Part Prefix'],['purchases','purchasePrefix','Purchase Prefix'],['receipts','transactionPrefix','Transaction Prefix'],['expenses','expensePrefix','Expense Prefix']];
function bankSettingsPanel(){let s=db.settings;return `<section class="panel"><div class="panelhead"><h2>Bank & Payment Gateway Details</h2></div><div class="panelbody"><p>Printed on invoices for customer payment. These details do not connect a payment gateway or initiate transfers.</p><div class="formgrid">${[{key:'bankName',label:'Bank Name & Branch'},{key:'bankAccount',label:'Account Number'},{key:'bankIfsc',label:'IFSC Code'},{key:'bankHolder',label:'Account Holder Name'}].map(f=>field(f,s)).join('')}</div><p>Manage BHIM UPI ID and QR in the UPI Scan Code section below.</p></div></section><section class="panel"><div class="panelhead"><h2>System ID Prefixes</h2></div><div class="panelbody"><p>Used for new records only. Existing record IDs remain unchanged.</p><div class="formgrid">${systemPrefixFields.map(([key,name,label])=>field({key:name,label,required:true},{...s,[name]:s[name]||prefixes[key]})).join('')}</div></div></section>`}
const settingsBeforeBankPrefix=settingsPage;
settingsPage=function(){let html=settingsBeforeBankPrefix();return html.replace('<div class="toolbar" style="margin-top:20px">',bankSettingsPanel()+'<div class="toolbar" style="margin-top:20px">')};
const nextBeforeAllPrefixes=nextId;
nextId=function(key){let config=systemPrefixFields.find(r=>r[0]===key);if(!config)return nextBeforeAllPrefixes(key);let prefix=String(db.settings[config[1]]||prefixes[key]).trim(),separator=prefix.endsWith('-')?'':'-',n=Math.max(1000,...db[key].map(r=>Number(String(r.id).split('~')[0].match(/(\d+)$/)?.[1])||1000))+1,id=prefix+separator+n;while(db[key].some(r=>r.id===id))id=prefix+separator+(++n);return id};
const bindBeforeBankPrefix=bindPage;
bindPage=function(){bindBeforeBankPrefix();let form=$('#settingsForm');if(form){let submit=form.onsubmit;form.onsubmit=e=>{let values=new FormData(form);for(let [,key,label]of systemPrefixFields){let value=String(values.get(key)||'').trim();if(!value||value.length>30||! /^[a-zA-Z0-9._-]+$/.test(value)){e.preventDefault();return toast(label+': use up to 30 letters, numbers, dot, dash or underscore.')}form.querySelector('[name="'+key+'"]').value=value}return submit(e)}}};
function invoiceBankMarkup(){let s=db.settings;if(![s.bankName,s.bankAccount,s.bankIfsc,s.bankHolder].some(Boolean))return '';return `<section class="invoiceBankDetails"><strong>Bank Details</strong>${[['Bank',s.bankName],['Account No.',s.bankAccount],['IFSC',s.bankIfsc],['Account Holder',s.bankHolder]].filter(([,v])=>v).map(([label,value])=>`<p><strong>${label}:</strong> ${esc(value)}</p>`).join('')}</section>`}
const invoiceBeforeBank=invoice;
invoice=function(key,id){invoiceBeforeBank(key,id);let sheet=$('#modalBody .invoice');if(sheet)sheet.insertAdjacentHTML('beforeend',invoiceBankMarkup())};
const thermalMarkupBeforeBank=thermalReceiptMarkup;
thermalReceiptMarkup=function(key,id,width){return thermalMarkupBeforeBank(key,id,width).replace('</article>',invoiceBankMarkup()+'</article>')};
const canvasBeforeBank=receiptCanvas;
receiptCanvas=function(key,id){let original=canvasBeforeBank(key,id);if(!invoiceBankMarkup())return original;let canvas=document.createElement('canvas');canvas.width=original.width;canvas.height=original.height+165;let x=canvas.getContext('2d');x.fillStyle='white';x.fillRect(0,0,canvas.width,canvas.height);x.drawImage(original,0,0);if(original.invoiceFooter)canvas.invoiceFooter=original.invoiceFooter;let s=db.settings,y=original.height+25;x.fillStyle='#111827';x.font='bold 18px Arial';x.fillText('Bank Details',35,y);x.font='18px Arial';for(let text of [s.bankName,'Account No: '+(s.bankAccount||'—')+'   IFSC: '+(s.bankIfsc||'—'),'Account Holder: '+(s.bankHolder||'—')]){y+=32;x.fillText(String(text||''),35,y)}return canvas};
render();
